import{_ as t,o,c as s,a3 as n}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"Centers","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/centers.md","filePath":"dev/domain/centers.md"}'),r={name:"dev/domain/centers.md"};function a(i,e,c,d,l,h){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="centers" tabindex="-1">Centers <a class="header-anchor" href="#centers" aria-label="Permalink to &quot;Centers&quot;">​</a></h1><p>The <strong>Centers</strong> module owns centers, the users who run them, and the center-facing API surface.</p><h2 id="state-and-status" tabindex="-1">State and status <a class="header-anchor" href="#state-and-status" aria-label="Permalink to &quot;State and status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Values</th><th>Controlled by</th><th>Meaning</th></tr></thead><tbody><tr><td><code>state</code></td><td><code>pending</code>, <code>active</code>, <code>blocked</code></td><td>Admin only</td><td>Gates every center-scoped endpoint. Only <code>centers.show</code> works unless the state is <code>active</code>.</td></tr><tr><td><code>status</code></td><td><code>visible</code>, <code>invisible</code></td><td>The center</td><td>Whether the center is listed to clients.</td></tr></tbody></table><p>Changing <code>state</code>, <code>status</code>, custom site or domain is admin-only. Clients only see <strong>visible, active</strong> centers.</p><h2 id="center-users" tabindex="-1">Center users <a class="header-anchor" href="#center-users" aria-label="Permalink to &quot;Center users&quot;">​</a></h2><ul><li>The <strong>primary user</strong> (<code>is_primary</code>, role <code>owner</code>) implicitly holds every center permission and can never be modified.</li><li>Other users get a list of <code>CenterUserPermission</code> values. A manager can only grant permissions they hold and cannot modify themselves.</li><li>Removing a user revokes their center tokens. A user with no centers left is soft-deleted.</li><li>Center login uses a phone OTP (<code>centers/auth/phone</code>, <code>centers/auth/phone/verify</code>); <code>POST centers/{center}/access</code> issues the center-scoped token and asks the primary user for their password again.</li><li>Admins list a center&#39;s users with <code>GET admin/centers/{center}/users</code> (<code>centers.view</code>), primary user first. With <code>otps.create</code>, <code>POST admin/centers/{center}/users/{user}/otp</code> issues a login code for one of them. See <a href="./support#admin-issued-codes">Support: OTP</a>.</li></ul><p>See <a href="./../conventions/permissions">Roles and permissions</a>.</p><h2 id="client-facing-endpoints" tabindex="-1">Client-facing endpoints <a class="header-anchor" href="#client-facing-endpoints" aria-label="Permalink to &quot;Client-facing endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET clients/centers</code></td><td>Paginated list of visible centers, optional <code>lat</code> and <code>lng</code> for distance</td></tr><tr><td><code>GET clients/centers/{slug}</code></td><td>Center details with an overview of its <strong>active</strong> services</td></tr><tr><td><code>GET/POST/DELETE clients/favorites</code></td><td>Favorites</td></tr><tr><td><code>POST clients/ratings</code></td><td>Rate a center</td></tr></tbody></table><p>The center details response lists each active service with <code>start_price</code> and <code>display_price</code>:</p><ul><li><code>start_price</code> is the lowest price option in halalas. For a <strong>Resort</strong>, add-ons (price options without a quantity) are not counted.</li><li><code>display_price</code> is <code>null</code>, or <code>{original, discounted, discount_amount, badge}</code> while an automatic offer lowers the start price right now. It comes from <code>ServicePriceDisplay</code> (see <a href="./promotions">Promotions</a>).</li></ul><h2 id="profile-completion-and-launch" tabindex="-1">Profile completion and launch <a class="header-anchor" href="#profile-completion-and-launch" aria-label="Permalink to &quot;Profile completion and launch&quot;">​</a></h2><p><code>GET centers/{center}/profile-completion</code> reports what is missing before a center can launch. <code>POST centers/launch</code> and <code>POST centers/register</code> create centers; admins can also create them.</p><h2 id="other-center-settings" tabindex="-1">Other center settings <a class="header-anchor" href="#other-center-settings" aria-label="Permalink to &quot;Other center settings&quot;">​</a></h2><p>Site theme (<code>site-theme</code>), social links (<code>social-links</code>) and the payout bank account (<code>payout-account</code>) are updated through their own endpoints. The center sees <strong>analytics</strong> at <code>centers/{center}/analytics</code>, and its purchases, clients, ledger and exports under the same prefix.</p><h2 id="business-rules" tabindex="-1">Business rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business rules&quot;">​</a></h2><ul><li>A center sees only its <strong>own clients</strong>: clients in <code>center_client</code>, or with a Confirmed or Completed purchase where the center is the merchant. Never list clients across centers.</li><li>Revenue and analytics count only <strong>Confirmed</strong> and <strong>Completed</strong> purchases where the center is the merchant, compared with the previous period of the same length. Analytics are center-wide and not narrowed by purchase visibility.</li><li>Center promotions apply only to that center&#39;s services. See <a href="./promotions">Promotions</a>.</li></ul>',18)])])}const m=t(r,[["render",a]]);export{p as __pageData,m as default};
